{
  "cvars": {
    "ivs": [
      {
        "description": "Instructor physical attractiveness: average beauty rating from six judges, standardized (z-score). Higher values = more attractive.",
        "columns": [
          "beauty_z"
        ]
      }
    ],
    "dv": {
      "description": "Teaching productivity operationalized as the course overall teaching evaluation score (student instructional rating; continuous, 1-5 scale).",
      "columns": [
        "eval"
      ]
    },
    "controls": [
      {
        "description": "Instructor age (years). Continuous control for experience/life-stage.",
        "is_moderator": false,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Class size: number of students who participated in the evaluation (continuous).",
        "is_moderator": false,
        "columns": [
          "students"
        ]
      },
      {
        "description": "Course enrollment (number of students enrolled). Used to compute response rate and as a control for course scale.",
        "is_moderator": false,
        "columns": [
          "allstudents"
        ]
      },
      {
        "description": "Student response rate: students / allstudents (proportion). Controls for sampling differences across classes.",
        "is_moderator": false,
        "columns": [
          "response_rate"
        ]
      },
      {
        "description": "Instructor gender (categorical: 'male' or 'female').",
        "is_moderator": false,
        "columns": [
          "gender"
        ]
      },
      {
        "description": "Instructor minority status (categorical: 'yes'/'no').",
        "is_moderator": false,
        "columns": [
          "minority"
        ]
      },
      {
        "description": "Course credit type (categorical: 'single' vs 'more').",
        "is_moderator": false,
        "columns": [
          "credits"
        ]
      },
      {
        "description": "Course division (categorical: 'lower' vs 'upper').",
        "is_moderator": false,
        "columns": [
          "division"
        ]
      },
      {
        "description": "Whether instructor is a native English speaker (categorical: 'yes'/'no').",
        "is_moderator": false,
        "columns": [
          "native"
        ]
      },
      {
        "description": "Whether the instructor is on the tenure track (categorical: 'yes'/'no').",
        "is_moderator": false,
        "columns": [
          "tenure"
        ]
      },
      {
        "description": "Instructor identifier (integer). Used for clustering standard errors and for professor fixed effects in one specification.",
        "is_moderator": false,
        "columns": [
          "prof"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure critical numeric columns exist and coerce types\n    numeric_cols = ['eval', 'beauty', 'age', 'students', 'allstudents']\n    for c in numeric_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop rows missing the dependent or primary independent variable\n    df = df.dropna(subset=['eval', 'beauty'])\n\n    # Compute response rate (students / allstudents). Guard against zero division.\n    df['response_rate'] = np.where(\n        (df['allstudents'].notna()) & (df['allstudents'] > 0),\n        df['students'] / df['allstudents'],\n        np.nan\n    )\n\n    # Standardize the beauty measure for easier interpretation\n    beauty_mean = df['beauty'].mean()\n    beauty_std = df['beauty'].std(ddof=0)\n    if pd.isna(beauty_std) or beauty_std == 0:\n        # fallback to avoid division by zero\n        df['beauty_z'] = df['beauty'] - beauty_mean\n    else:\n        df['beauty_z'] = (df['beauty'] - beauty_mean) / beauty_std\n\n    # Convert categorical controls to category dtype to be used with C(...) in formulas\n    cat_cols = ['gender', 'minority', 'credits', 'division', 'native', 'tenure']\n    for c in cat_cols:\n        if c in df.columns:\n            df[c] = df[c].astype('category')\n\n    # Ensure prof is integer for clustering / fixed effects\n    if 'prof' in df.columns:\n        df['prof'] = pd.to_numeric(df['prof'], errors='coerce')\n\n    # Return dataframe containing all variables used in modeling\n    required_cols = [\n        'eval', 'beauty', 'beauty_z', 'age', 'students', 'allstudents', 'response_rate',\n        'gender', 'minority', 'credits', 'division', 'native', 'tenure', 'prof'\n    ]\n    # Keep only columns that exist to avoid KeyError downstream; but leave dataframe intact\n    # (model function will drop missing values as needed).\n    return df",
  "m_code": "def model(df: pd.DataFrame) -> dict:\n    import statsmodels.formula.api as smf\n    results = {}\n\n    # Work on a copy of the transformed df and drop rows missing columns required for each model\n    df_mod = df.copy()\n\n    # Model 1: simple bivariate relationship (beauty -> eval)\n    m1_df = df_mod.dropna(subset=['eval', 'beauty_z'])\n    m1 = smf.ols('eval ~ beauty_z', data=m1_df).fit(cov_type='HC3')\n    results['model_simple'] = m1\n\n    # Model 2: add observed controls and cluster standard errors by professor (prof) if available\n    controls = [\n        'age', 'students', 'response_rate',\n        'C(gender)', 'C(minority)', 'C(credits)', 'C(division)', 'C(native)', 'C(tenure)'\n    ]\n    formula_controls = ' + '.join(controls)\n    formula2 = f'eval ~ beauty_z + {formula_controls}'\n\n    # drop rows with any of the required predictors missing\n    required_m2 = ['eval', 'beauty_z', 'age', 'students', 'response_rate']\n    # include categorical columns (they may be present but could be NA)\n    cat_required = ['gender', 'minority', 'credits', 'division', 'native', 'tenure']\n    for c in cat_required:\n        if c in df_mod.columns:\n            required_m2.append(c)\n\n    m2_df = df_mod.dropna(subset=[c for c in required_m2 if c in df_mod.columns])\n\n    if 'prof' in m2_df.columns and m2_df['prof'].notna().any():\n        # cluster by prof when available\n        m2 = smf.ols(formula2, data=m2_df).fit(cov_type='cluster', cov_kwds={'groups': m2_df['prof']})\n    else:\n        m2 = smf.ols(formula2, data=m2_df).fit(cov_type='HC3')\n    results['model_controls_clustered'] = m2\n\n    # Model 3: include professor fixed effects to absorb unobserved instructor-level heterogeneity\n    # (this will estimate the beauty effect controlling for any time-invariant prof-level factors)\n    if 'prof' in df_mod.columns:\n        # include prof as categorical fixed effect; drop rows missing prof or beauty_z or eval\n        m3_df = df_mod.dropna(subset=['eval', 'beauty_z', 'prof'])\n        # Build formula adding professor fixed effects\n        formula3 = f'eval ~ beauty_z + {formula_controls} + C(prof)'\n        # Fit with robust (HC3) standard errors; clustering by prof isn't meaningful with C(prof) included\n        m3 = smf.ols(formula3, data=m3_df).fit(cov_type='HC3')\n        results['model_prof_fe'] = m3\n    else:\n        results['model_prof_fe'] = None\n\n    # Return the fitted results objects (statsmodels RegressionResults). The caller can call .summary().\n    return results"
}

{
  "cvars": {
    "ivs": [
      {
        "description": "Instructor attractiveness as rated by a panel (beauty). Standardized to mean 0, SD 1 for interpretability. This is the main independent variable of interest.",
        "columns": [
          "beauty_z"
        ]
      }
    ],
    "dv": {
      "description": "Student instructional rating (course overall teaching evaluation score). Higher values indicate better evaluations.",
      "columns": [
        "eval"
      ]
    },
    "controls": [
      {
        "description": "Instructor age in years (continuous).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age"
        ]
      },
      {
        "description": "Instructor gender: indicator equal to 1 if female, 0 if male.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "gender_female"
        ]
      },
      {
        "description": "Instructor minority status: indicator equal to 1 if non-Caucasian (yes), 0 if no.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "minority_yes"
        ]
      },
      {
        "description": "Course credit type: indicator equal to 1 if course is 'more' credits (not a single-credit elective), 0 if 'single'.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "credits_more"
        ]
      },
      {
        "description": "Course division: indicator equal to 1 if upper-division, 0 if lower-division.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "division_upper"
        ]
      },
      {
        "description": "Instructor native English speaker: indicator equal to 1 if native = 'yes', 0 if 'no'.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "native_yes"
        ]
      },
      {
        "description": "Instructor tenure status: indicator equal to 1 if on tenure track (yes), 0 if not.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "tenure_yes"
        ]
      },
      {
        "description": "Class size (log of number of students who participated in the evaluation). Log-transform to reduce skew.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ln_students"
        ]
      },
      {
        "description": "Professor identifier (used for clustered standard errors and for an alternative fixed-effects specification).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "prof"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Prepare data for analysis of the effect of instructor beauty on student evaluations.\n\n    Outputs (appended to df):\n      - beauty_z: standardized beauty score (mean 0, sd 1)\n      - beauty_z_sq: squared standardized beauty (for optional nonlinearity checks)\n      - gender_female, minority_yes, credits_more, division_upper, native_yes, tenure_yes: binary indicators (0/1)\n      - ln_students: natural log of 'students'\n      - eval: dependent variable (kept as-is)\n      - prof: professor identifier (kept as-is)\n\n    Rows with missing values in the key variables are dropped.\n    \"\"\"\n    df = df.copy()\n\n    # Required columns list\n    required = ['beauty', 'eval', 'age', 'gender', 'students', 'minority', 'credits', 'division', 'native', 'tenure', 'prof']\n    # Drop rows missing any required field\n    df = df.dropna(subset=required)\n\n    # Standardize beauty for interpretability\n    df['beauty_z'] = (df['beauty'] - df['beauty'].mean()) / (df['beauty'].std(ddof=0) if df['beauty'].std(ddof=0) != 0 else 1.0)\n    # optional squared term in case of nonlinear effects\n    df['beauty_z_sq'] = df['beauty_z'] ** 2\n\n    # Binary indicators from categorical fields (explicit mappings to ensure reproducibility)\n    df['gender_female'] = (df['gender'].astype(str).str.lower() == 'female').astype(int)\n    df['minority_yes'] = (df['minority'].astype(str).str.lower() == 'yes').astype(int)\n    df['credits_more'] = (df['credits'].astype(str).str.lower() == 'more').astype(int)\n    df['division_upper'] = (df['division'].astype(str).str.lower() == 'upper').astype(int)\n    df['native_yes'] = (df['native'].astype(str).str.lower() == 'yes').astype(int)\n    df['tenure_yes'] = (df['tenure'].astype(str).str.lower() == 'yes').astype(int)\n\n    # Log-transform number of students who participated to reduce skew\n    # Add a small constant to avoid log(0) in pathological cases (there are no zeros per schema, but defensive coding)\n    df['ln_students'] = np.log(df['students'].astype(float) + 1e-6)\n\n    # Ensure eval is numeric\n    df['eval'] = pd.to_numeric(df['eval'], errors='coerce')\n\n    # Final drop for any newly coerced NaNs\n    df = df.dropna(subset=['beauty_z', 'eval', 'age', 'ln_students', 'prof'])\n\n    # Keep only columns necessary for modeling plus identifiers for traceability\n    keep_cols = ['beauty', 'beauty_z', 'beauty_z_sq', 'eval', 'age', 'gender_female', 'minority_yes', 'credits_more', 'division_upper', 'native_yes', 'tenure_yes', 'ln_students', 'prof']\n    # If any keep_cols are missing (shouldn't be), create them as NA to avoid KeyError\n    for c in keep_cols:\n        if c not in df.columns:\n            df[c] = np.nan\n\n    return df[keep_cols]\n",
  "m_code": "def model(df: pd.DataFrame) -> dict:\n    \"\"\"\n    Runs two OLS specifications to estimate the effect of instructor beauty on student evaluations.\n\n    1) Baseline OLS with controls and professor-clustered standard errors.\n    2) OLS with professor fixed effects (C(prof)) and controls as a robustness check.\n\n    Returns a dictionary with the fitted results objects:\n      - 'clustered': OLS results with clustered SE by prof\n      - 'fe': OLS results with professor fixed effects\n\n    Usage: results = model(transformed_df)\n    \"\"\"\n    import statsmodels.api as _sm\n    import statsmodels.formula.api as _smf\n\n    # Ensure required columns exist\n    needed = ['beauty_z', 'eval', 'age', 'gender_female', 'minority_yes', 'credits_more', 'division_upper', 'native_yes', 'tenure_yes', 'ln_students', 'prof']\n    missing = [c for c in needed if c not in df.columns]\n    if len(missing) > 0:\n        raise ValueError(f\"Missing columns required for modeling: {missing}\")\n\n    # Baseline OLS with controls\n    X_cols = ['beauty_z', 'age', 'gender_female', 'minority_yes', 'credits_more', 'division_upper', 'native_yes', 'tenure_yes', 'ln_students']\n    X = _sm.add_constant(df[X_cols])\n    y = df['eval']\n\n    model_cluster = _sm.OLS(y, X).fit(cov_type='cluster', cov_kwds={'groups': df['prof']})\n\n    # Robustness: professor fixed effects (lots of dummies) using formula API\n    formula = 'eval ~ beauty_z + age + gender_female + minority_yes + credits_more + division_upper + native_yes + tenure_yes + ln_students + C(prof)'\n    model_fe = _smf.ols(formula, data=df).fit()\n\n    # Return both fitted models; callers can inspect .summary() or coefficients\n    return {\n        'clustered': model_cluster,\n        'fe': model_fe\n    }\n"
}
